// Transparent, rule-based urgency scoring. Edit keywords and weights in the Config node.
const cfg = $('Config').first().json;
const list = (s) => String(s || '').split(',').map((x) => x.trim().toLowerCase()).filter(Boolean);
const keywords = list(cfg.urgentKeywords);
const vipDomains = list(cfg.vipDomains);
const threshold = Number(cfg.urgencyThreshold) || 2;

return $('Watch support inbox').all().map((email) => {
  const j = email.json;
  const sender = j.from?.value?.[0] || {};
  const from = String(sender.address || '').toLowerCase();
  const fromName = sender.name || from.split('@')[0] || 'there';
  const subject = String(j.subject || '').trim();
  const body = String(j.text || '').slice(0, 8000);
  const subjectLc = subject.toLowerCase();
  const bodyLc = body.toLowerCase();

  const has = (text, k) => new RegExp(`(^|[^a-z0-9])${k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}([^a-z0-9]|$)`).test(text);
  const inBody = keywords.filter((k) => has(bodyLc, k));
  const inSubject = keywords.filter((k) => has(subjectLc, k));
  const matched = [...new Set([...inSubject, ...inBody])];

  let score = inBody.length + inSubject.length * 2;
  const reasons = [];
  if (/!{2,}/.test(subject) || (subject.length > 8 && subject === subject.toUpperCase() && /[A-Z]/.test(subject))) { score += 1; reasons.push('shouting subject'); }
  const domain = from.split('@')[1] || '';
  if (vipDomains.includes(domain)) { score += 2; reasons.push('VIP domain'); }

  const headers = j.headers || {};
  const headerText = JSON.stringify(headers).toLowerCase();
  const isAutomated = /(^|[._-])(no-?reply|do-?not-?reply|mailer-daemon|postmaster|bounce)/.test(from)
    || /^(auto(matic)?[ -]?reply|out of (the )?office|undeliverable|delivery status notification)/i.test(subject)
    || /auto-submitted"?:\s*"?auto-(replied|generated)|precedence"?:\s*"?(bulk|junk|list)/.test(headerText);

  return {
    json: {
      received_at: new Date(j.date || Date.now()).toISOString(),
      from,
      from_name: fromName,
      first_name: String(fromName).split(/\s+/)[0],
      subject: subject || '(no subject)',
      preview: body.replace(/\s+/g, ' ').trim().slice(0, 280),
      score,
      priority: score >= threshold ? 'urgent' : 'normal',
      matched_keywords: matched.join(', '),
      reasons: reasons.join(', '),
      is_automated: isAutomated,
    },
  };
});
